#[cfg(target_arch = "aarch64")]
#[target_feature(enable = "neon")]
#[inline]
unsafe fn unpack_neon_unrolled(ip: *const u32, dp: *mut u32, bits: u8, mask: uint32x4_t) {
    // SAFETY: forwarded to the per-width kernel; see `unpack`.
    unsafe {
        match bits {
            1 => unpack_w1(ip, dp, mask),
            2 => unpack_w2(ip, dp, mask),
            3 => unpack_w3(ip, dp, mask),
            4 => unpack_w4(ip, dp, mask),
            5 => unpack_w5(ip, dp, mask),
            6 => unpack_w6(ip, dp, mask),
            7 => unpack_w7(ip, dp, mask),
            8 => unpack_w8(ip, dp, mask),
            9 => unpack_w9(ip, dp, mask),
            10 => unpack_w10(ip, dp, mask),
            11 => unpack_w11(ip, dp, mask),
            12 => unpack_w12(ip, dp, mask),
            13 => unpack_w13(ip, dp, mask),
            14 => unpack_w14(ip, dp, mask),
            15 => unpack_w15(ip, dp, mask),
            16 => unpack_w16(ip, dp, mask),
            17 => unpack_w17(ip, dp, mask),
            18 => unpack_w18(ip, dp, mask),
            19 => unpack_w19(ip, dp, mask),
            20 => unpack_w20(ip, dp, mask),
            21 => unpack_w21(ip, dp, mask),
            22 => unpack_w22(ip, dp, mask),
            23 => unpack_w23(ip, dp, mask),
            24 => unpack_w24(ip, dp, mask),
            25 => unpack_w25(ip, dp, mask),
            26 => unpack_w26(ip, dp, mask),
            27 => unpack_w27(ip, dp, mask),
            28 => unpack_w28(ip, dp, mask),
            29 => unpack_w29(ip, dp, mask),
            30 => unpack_w30(ip, dp, mask),
            31 => unpack_w31(ip, dp, mask),
            _ => unreachable!("bits 1..=31"),
        }
    }
}
